'use strict';
/* Red Riot Racing — editorial rebuild. Content stays editable in /data/*.json via Pages CMS. */
const $=selector=>document.querySelector(selector);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=value=>{try{const x=new URL(value,location.origin);return ['https:','http:','mailto:'].includes(x.protocol)?x.href:''}catch{return''}};
const srcURL=value=>{if(!value)return'';try{const x=new URL(value,location.origin);if(!['https:','http:'].includes(x.protocol))return'';return x.href}catch{return''}};
const external=(value,label,classes='view-link')=>{const url=safeURL(value);return url?`<a class="${classes}" href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">${label}${classes.includes('view-link')?'<span aria-hidden="true">↗</span>':''}</a>`:''};
const localLink=(href,label,classes='view-link')=>`<a class="${classes}" href="${href}">${label}${classes.includes('view-link')?'<span aria-hidden="true">↗</span>':''}</a>`;
const cmsPlain=value=>typeof value==='string'?value.trim():'';
const cmsURL=value=>{if(typeof value!=='string'||!value.trim())return '';try{const parsed=new URL(value,location.origin);return ['http:','https:','mailto:'].includes(parsed.protocol)?parsed.href:''}catch{return''}};
function cmsHeadline(raw){const lines=String(raw).split('|').map(x=>x.trim()).filter(Boolean);return lines.map(line=>{const parts=line.split(/(\*[^*]+\*)/g).map(chunk=>chunk.startsWith('*')&&chunk.endsWith('*')?`<em class="rich">${escapeHTML(chunk.slice(1,-1))}</em>`:escapeHTML(chunk)).join('');return `<span class="cms-headline-line">${parts.replace(/\.$/, '<span class="cms-custom-period">.</span>')}</span>`}).join('')}
function cmsApply(page,config){if(!config||typeof config!=='object')return;const fields=CMS_SELECTORS[page]||{};for(const [key,[selector,mode]] of Object.entries(fields)){const value=config[key],elements=document.querySelectorAll(selector);if(mode==='visible'){if(value===false)elements.forEach(el=>{el.hidden=true;el.style.display='none'});continue}if(typeof value!=='string'||!value.trim())continue;elements.forEach(el=>{if(mode==='text')el.textContent=value;if(mode==='headline'){el.innerHTML=cmsHeadline(value);el.classList.add('cms-custom-headline')}if(mode==='button'){const arrow=el.textContent.includes('↗')?' ↗':'';el.textContent=value.trim()+arrow}if(mode==='url'){const href=cmsURL(value);if(href)el.setAttribute('href',href)}})}}
