function socialQuickLinks(site,placement='section'){
 const links=[['Instagram',site.instagram_url,'instagram'],['Facebook',site.facebook_url,'facebook'],['TikTok',site.tiktok_url,'tiktok'],['YouTube',site.youtube_url,'youtube'],['LinkedIn',site.linkedin_url,'linkedin']].filter(([,url])=>safeURL(url));
 return links.map(([name,url,slug])=>`<a class="rr-v52-social-link rr-v52-${slug}" href="${escapeHTML(safeURL(url))}" target="_blank" rel="noopener noreferrer" aria-label="Red Riot Racing on ${name}"><span class="rr-v52-social-symbol" aria-hidden="true">${name==='Instagram'?'◎':name==='Facebook'?'f':name==='YouTube'?'▶':name==='TikTok'?'♪':'in'}</span><span class="rr-v52-social-name">${name}</span><span aria-hidden="true">↗</span></a>`).join('')
}
