function footer(site){const social=[['Instagram',site.instagram_url],['Facebook',site.facebook_url],['TikTok',site.tiktok_url],['YouTube',site.youtube_url],['LinkedIn',site.linkedin_url]].filter(([k,v])=>safeURL(v));return `<footer class="footer"><div class="shell"><div class="footer-grid"><div><a class="wordmark" href="/" aria-label="Red Riot Racing home"><img class="rr-official-logo" src="/assets/official-red-riot-logo-transparent.png" alt="Red Riot Racing by McPherson College"></a><p class="footer-description">${escapeHTML(site.footer_note||'A new student Formula SAE program building toward the 2028 season.')}</p></div><div><span class="footer-heading">Explore / 01</span><div class="footer-links">${NAV.map(([t,url])=>`<a href="${url}">${t}</a>`).join('')}<a href="/contact.html">Contact</a></div></div><div><span class="footer-heading">Follow / 02</span><div class="footer-links">${social.map(([name,href])=>`<a href="${escapeHTML(safeURL(href))}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`).join('')}${social.length===0?'<span>Official social channels coming soon</span>':''}<a href="https://www.sae.org/events/student/about/formula" target="_blank" rel="noopener noreferrer">About Formula SAE ↗</a></div></div></div><div class="rr-v52-footer-social"><strong>STAY IN THE LOOP.</strong><div>${socialQuickLinks(site,'footer')}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Red Riot Racing — McPherson College</span><span>Student-led motorsport / First competition target: 2028</span></div></div></footer>`}
