const [cmsPage,cmsNav,cmsSite,cmsTiers]=await Promise.all([
loadJSON('/data/editor-'+({'Home':'home','About':'about','Leadership':'leadership','Road to 2028':'road','Sponsors':'sponsors','Updates':'updates','Merch':'merch','Contact':'contact'}[page]||'home')+'.json',{}),
loadJSON('/data/editor-navigation.json',{}),loadJSON('/data/editor-site.json',{}),loadJSON('/data/editor-sponsor-tiers.json',{})]);
cmsApply(page,cmsPage);
if(Array.isArray(cmsNav.menu)&&cmsNav.menu.length){const nav=$('#site-menu');if(nav){const sponsorLink=nav.querySelector('.nav-sponsor');const entries=cmsNav.menu.filter(x=>x&&x.visible!==false&&cmsURL(x.href)&&cmsPlain(x.label));nav.querySelectorAll('a:not(.nav-sponsor)').forEach(el=>el.remove());for(const item of entries){const a=document.createElement('a');a.textContent=item.label;a.href=cmsURL(item.href);if(a.pathname===location.pathname){a.className='current';a.setAttribute('aria-current','page')}nav.insertBefore(a,sponsorLink)}}}
if(cmsNav.top_strip_left){const el=document.querySelector('.top-strip span:first-child');if(el)el.textContent=cmsNav.top_strip_left}
if(cmsNav.top_strip_right){const el=document.querySelector('.top-strip span:last-child');if(el)el.textContent=cmsNav.top_strip_right}
const navSponsor=$('.nav-sponsor');if(navSponsor){if(cmsNav.sponsor_button_label)navSponsor.textContent=cmsNav.sponsor_button_label+' ↗';if(cmsURL(cmsNav.sponsor_button_url))navSponsor.href=cmsURL(cmsNav.sponsor_button_url)}
if(cmsSite.announcement_visible===true&&cmsPlain(cmsSite.announcement_text)){const banner=document.createElement('div');banner.className='cms-announcement';banner.textContent=cmsSite.announcement_text;document.querySelector('.top-strip')?.after(banner)}
if(cmsSite.social_links_visible===false){document.querySelectorAll('.footer-grid>div:nth-child(3) .footer-links a:not(:last-child), .rr-v52-nav-social, .rr-v52-footer-social, .rr-v52-social-section').forEach(el=>el.style.display='none')}
if(cmsSite.default_meta_description){let tag=document.querySelector('meta[name="description"]');if(!tag){tag=document.createElement('meta');tag.name='description';document.head.appendChild(tag)}tag.content=cmsSite.default_meta_description}
